def svg_diagram(uid, title, desc, nodes, caption, incident=False):
    """Small, accessible SVG with explicit local icons on every labeled node."""
    width, height = 1120, (360 if incident else 690)
    x_positions = [35, 255, 475, 695, 915] if incident else [85, 425, 765]
    y_positions = [125] * 5 if incident else [105, 270, 455]
    box_w, box_h = (170, 150) if incident else (250, 112)
    elems = [f'<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-labelledby="{uid}-title {uid}-desc" viewBox="0 0 {width} {height}" width="100%" height="auto" style="min-width:900px;background:#0f172a;border:1px solid #334155;border-radius:8px">',
             f'<title id="{uid}-title">{escape(title)}</title><desc id="{uid}-desc">{escape(desc)}</desc>',
             '<defs><marker id="%s-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#67e8f9"/></marker></defs>' % uid]
    if not incident:
        for i, (label, _, _) in enumerate(nodes):
            y = [55, 220, 405][i]
            color = ['#0c4a6e', '#14532d', '#713f12'][i]
            tier = ['TIER 1 · LEARNER AND LOCAL ENVIRONMENT', 'TIER 2 · STUDY AND EVIDENCE WORKFLOW', 'TIER 3 · REVIEW AND OWNERSHIP'][i]
            elems.append(f'<rect x="20" y="{y}" width="1080" height="145" rx="8" fill="{color}" opacity=".48"/><text x="36" y="{y+22}" fill="#e2e8f0" font-family="sans-serif" font-size="14" font-weight="bold">{tier}</text>')
    else:
        elems.append('<rect x="245" y="82" width="390" height="208" rx="8" fill="none" stroke="#f59e0b" stroke-width="2" stroke-dasharray="7 5"/><text x="440" y="304" text-anchor="middle" fill="#fbbf24" font-family="sans-serif" font-size="12">TABLETOP VERIFICATION BOUNDARY · predicted behavior only</text>')
    for i, (label, detail, icon) in enumerate(nodes):
        x, y = x_positions[i], y_positions[i]
        if i:
            prev = x_positions[i-1]
            elems.append(f'<line x1="{prev+box_w}" y1="{y+box_h/2}" x2="{x-8}" y2="{y+box_h/2}" stroke="#67e8f9" stroke-width="3" marker-end="url(#{uid}-arrow)"/>')
        elems.append(f'<rect x="{x}" y="{y}" width="{box_w}" height="{box_h}" rx="9" fill="#111827" stroke="#38bdf8" stroke-width="2"/>')
        if incident and i == 1:
            elems.append(f'<rect x="{x+box_w-43}" y="{y+5}" width="36" height="19" rx="4" fill="#7f1d1d"/><text x="{x+box_w-25}" y="{y+19}" text-anchor="middle" fill="#fecaca" font-family="sans-serif" font-size="11" font-weight="bold">FI</text>')
        elems.append(f'<image href="{escape(ICON[icon])}" x="{x+box_w/2-25}" y="{y+12}" width="50" height="50" preserveAspectRatio="xMidYMid meet"/>')
        elems.append(f'<text x="{x+box_w/2}" y="{y+82}" text-anchor="middle" fill="#f8fafc" font-family="sans-serif" font-size="14" font-weight="bold">{escape(label)}</text>')
        elems.append(f'<text x="{x+box_w/2}" y="{y+105}" text-anchor="middle" fill="#cbd5e1" font-family="sans-serif" font-size="11">{escape(detail)}</text>')
    elems += ['</svg>', f'<figcaption>{escape(caption)}</figcaption>']
    return '<figure class="diagram-container"><div style="max-width:100%;overflow-x:auto">' + ''.join(elems) + '</div>' + ('' if incident else '') + '</figure>'

