# Keep runnable commands in copyable blocks rather than inline formatting.
for _topic in TOPICS:
    for _i, _step in enumerate(_topic["lab"]["steps"]):
        _topic["lab"]["steps"][_i] = re.sub(
            r"`((?:pwd|git|mkdir|cd|printf|cat|bash|ls)(?:\s|$)[^`]+)`",
            lambda m: "```bash\n" + m.group(1) + "\n```",
            _step,
        )
